class Car:
    def __init__(self, make, model):
        self.make = make
        self.model = model
        self.maintenance_log = []

    def add_service(self, date, description):
        service = {'date': date, 'description': description}
        self.maintenance_log.append(service)

    def get_service_history(self):
        history = ""
        for service in self.maintenance_log:
            history += f"Date: {service['date']} - {service['description']}\n"

        return history

my_car = Car('Toyota', 'Corolla')
my_car.add_service('2020-01-15', 'Oil change')
my_car.add_service('2020-06-20', 'Tire rotation')
print(my_car.get_service_history())

