import random
MIN_GUESS = 1
MAX_GUESS = 100

def get_guess():
    guess = input("Make a guess: ")

    if guess.strip() == "":
        return None

    try:
        guess = int(guess)
    except ValueError:
        print(f"Invalid input {guess}. Please enter a number between {MIN_GUESS} and {MAX_GUESS}.")
        return None

    if guess < MIN_GUESS or guess > MAX_GUESS:
        print(f"Guess {guess} is out of range. Please enter a number between {MIN_GUESS} and {MAX_GUESS}.")
        return None

    return guess

def game():
    num_to_guess = random.randint(MIN_GUESS, MAX_GUESS)
    guesses = 0

    while True:
        guess = get_guess()

        if guess is None:
            continue

        guesses += 1

        if guess == num_to_guess:
            print(f"You guessed it in {guesses} tries! Congrats!")
            return

        if guess > num_to_guess:
            print("Too high.")
        else:
            print("Too low.")

if __name__ == "__main__":
    game()

