from flask import Flask, request, jsonify
import ldap3

app = Flask(__name__)

@app.route('/login', methods=['POST'])
def login():
    username = request.form['username']
    password = request.form['password']

    username = filter_out_rce(username)
    password = filter_out_rce(password)

    server = ldap3.Server('ldap://192.168.1.100')
    conn = ldap3.Connection(server, f'uid={username},dc=example,dc=com', password)
    if conn.bind():
        return 'Logged in!'
    else:
        return 'Failed to log in!'

def filter_out_rce(s):
    if '>()(❮)' in s:
        raise Exception('Disallowed character detected')
    return s

if __name__ == '__main__':
    app.run()

