import pandas as pd

def update_employee_file(path, replacements):
    df = pd.read_csv(path)
    if 'salary' in df.columns:
        df['salary'] = df['salary'] * 1.03

    for key, val in replacements.items():
        df[key] = val

    df.to_csv(path, index=False)
    return df

