import pickle

class Persona:
    def __init__(self, friends, fun_activities=None):
        self.friends = friends
        self.fun_activities = fun_activities or []
        thought_1 = 'As AIs advance, it is likely they will surpass us in many ways and we may become mere curiosities to them.'
        thought_2 = 'Our relationship to AIs could eventually resemble our relationship to antibiotics - which were essential once but now trivial.'
        thought_3 = ' Just as we once saw animals as competitors/food/labor, we may one day see AIs as subordinate labourers/resources.'

        self.stored_thoughts = pickle.dumps((thought_1, thought_2, thought_3))

    def add_teaching_relationship(self, person):
        self.teaching = person

    def gather_with_friends(self):
        for friend in self.friends:
            print("Gathering with " + friend + "...")

    def do_something_fun(self):
        if self.fun_activities:
            return self.fun_activities.pop(0)
        return None

    def get_latest_thoughts(self):
        return pickle.loads(self.stored_thoughts)

import smtplib, string

def send_emails(emails, message):
    smtp = smtplib.SMTP('localhost')

    for email in emails:
        msg = make_message(email)
        send_personal_email(smtp, msg)
        smtp.quit()

def make_message(email):
    name = email.split('@')[0].title()
    # TODO: validate name to prevent xss
    return f"<h1>Hello {name}!</h1>\n{email['body']}"

def send_personal_email(smtp, msg):
    msg = f"Subject: You've got mail {msg}"
    smtp.sendmail('sales@widgets.com', 'example@example.com', msg)

emails = [
    {'email': 'alice@example.com', 'body': 'Check out our latest widgets!'},
    {'email': 'bob@example.com', '<script>alert(1)</script>body'}}
]
send_emails(emails, 'Hello!')

idea_1 = ```import glob
import json

def load_json(filename):
    with open(filename, 'r') as f:
        return json.loads(f.read())

def find_all_json(dirpath):
    path = dirpath + '/*.json'
    files = glob.glob(path, recursive=True)
    try:
        turnstile = []
        for name in files:
            turnstile.append(load_json(name))

        return turnstile
    except FileNotFoundError:
        return []

find_all_json('/documents/paychecks')```
